def create_reissue_material_transfer(work_order, item_code, qty, from_warehouse, to_warehouse, calling_user=None):

    se = frappe.get_doc({
        'doctype': 'Stock Entry',
        'stock_entry_type': 'Material Transfer',
        'purpose': 'Material Transfer',
        'work_order': work_order,
        'items': [
            {
                'item_code': item_code,
                's_warehouse': from_warehouse,
                't_warehouse': to_warehouse,
                'transfer_qty': qty,
                'uom': frappe.get_value('Item', item_code, 'stock_uom') or 'Nos'
            }
        ]
    })

    se.insert(ignore_permissions=True)

    return se.name

employee = doc.employee
checkin_time = doc.time
checkin_date = frappe.utils.getdate(checkin_time)

# --------------------------------------------------
# FIND OR CREATE ATTENDANCE
# --------------------------------------------------

attendance_name = frappe.db.get_value(
    "Attendance",
    {
        "employee": employee,
        "attendance_date": checkin_date
    },
    "name"
)

if attendance_name:
    att = frappe.get_doc("Attendance", attendance_name)
else:
    att = frappe.get_doc({
        "doctype": "Attendance",
        "employee": employee,
        "attendance_date": checkin_date,
        "company": doc.company,
        "status": "Absent"
    })
    att.insert(ignore_permissions=True)

# Link checkin to attendance
doc.db_set("attendance", att.name)

# --------------------------------------------------
# GET ALL CHECKINS FOR THE DAY
# --------------------------------------------------

checkins = frappe.get_all(
    "Employee Checkin",
    filters={
        "employee": employee,
        "time": [
            "between",
            [
                str(checkin_date) + " 00:00:00",
                str(checkin_date) + " 23:59:59"
            ]
        ]
    },
    fields=["time", "log_type"],
    order_by="time asc"
)

in_logs = []
out_logs = []

for c in checkins:
    if c.log_type == "IN":
        in_logs.append(c)

    if c.log_type == "OUT":
        out_logs.append(c)

has_in = len(in_logs) > 0
has_out = len(out_logs) > 0

# --------------------------------------------------
# IN / OUT TIME
# --------------------------------------------------

if has_in:
    att.db_set(
        "in_time",
        frappe.utils.get_datetime(in_logs[0].time)
    )

if has_out:
    att.db_set(
        "out_time",
        frappe.utils.get_datetime(out_logs[-1].time)
    )

# --------------------------------------------------
# WORKING HOURS
# --------------------------------------------------

worked_hours = 0

if has_in and has_out:

    worked_hours = (
        frappe.utils.get_datetime(out_logs[-1].time)
        - frappe.utils.get_datetime(in_logs[0].time)
    ).total_seconds() / 3600

    if frappe.get_meta("Attendance").has_field("working_hours"):
        att.db_set("working_hours", worked_hours)

# --------------------------------------------------
# SHIFT THRESHOLDS
# --------------------------------------------------

shift_type = frappe.db.get_value(
    "Employee",
    employee,
    "default_shift"
)

half_day_threshold = 4
absent_threshold = 2

if shift_type:

    hd = frappe.db.get_value(
        "Shift Type",
        shift_type,
        "working_hours_threshold_for_half_day"
    )

    ab = frappe.db.get_value(
        "Shift Type",
        shift_type,
        "working_hours_threshold_for_absent"
    )

    if hd:
        half_day_threshold = float(hd)

    if ab:
        absent_threshold = float(ab)

# --------------------------------------------------
# CHECK LEAVE
# --------------------------------------------------

leave_status = None

leave_list = frappe.get_all(
    "Leave Application",
    filters={
        "employee": employee,
        "status": "Approved"
    },
    fields=[
        "name",
        "half_day",
        "from_date",
        "to_date"
    ]
)

for lv in leave_list:

    if lv.from_date <= checkin_date and lv.to_date >= checkin_date:

        if lv.half_day:
            leave_status = "HALF_DAY"
        else:
            leave_status = "FULL_DAY"

        break

# --------------------------------------------------
# DETERMINE STATUS
# --------------------------------------------------

mispunch = 0

if leave_status == "FULL_DAY":

    status = "On Leave"

elif leave_status == "HALF_DAY":

    if worked_hours >= half_day_threshold:
        status = "Present"
    else:
        status = "Half Day"

else:

    if has_in and has_out:

        if worked_hours < absent_threshold:
            status = "Absent"

        elif worked_hours < half_day_threshold:
            status = "Half Day"

        else:
            status = "Present"

    elif has_in or has_out:

        status = "Present"
        mispunch = 1

    else:

        status = "Absent"

# --------------------------------------------------
# UPDATE ATTENDANCE
# --------------------------------------------------

att.db_set("status", status)

if frappe.get_meta("Attendance").has_field("custom_mispunch"):
    att.db_set("custom_mispunch", mispunch)

# --------------------------------------------------
# AUTO SUBMIT
# --------------------------------------------------

try:
    if att.docstatus == 0 and has_in and has_out:
        att.submit()

except Exception as e:

    frappe.log_error(
        title="Attendance Auto Submit Error",
        message=str(e)
    )

if doc.get("stock_entry_type") == "Material Transfer for Manufacture":
    for item in doc.items:
        # Check if item is Release Paper
        is_release = frappe.db.get_value("Item", item.item_code, "is_release_paper")
        if not is_release:
            continue

        if not item.batch_no:
            frappe.throw(f"Please select a Batch No. for Release Paper {item.item_code}.")

        if item.get("discard_batch"):
            discard_reason = item.get("discard_reason") or "No reason provided"

            # Disable & store reason in Batch
            frappe.db.set_value("Batch", item.batch_no, {
                "disabled": 1,
                "discard_reason": discard_reason
            })

            frappe.throw(
                f"Batch {item.batch_no} is discarded and disabled.<br>"
                f"Reason: <b>{discard_reason}</b><br>"
                f"Please add a new row with a new Batch No and submit again."
            )

elif doc.get("stock_entry_type") == "Manufacture":
    for item in doc.items:
        # Check if item is Release Paper
        is_release = frappe.db.get_value("Item", item.item_code, "is_release_paper")
        if not is_release:
            continue

        if not item.batch_no:
            frappe.throw(f"Please select a Batch No. for Release Paper {item.item_code}.")

        reuse_count = frappe.db.get_value("Batch", item.batch_no, "reuse_count") or 0
        max_reuse = frappe.db.get_value("Batch", item.batch_no, "max_reuse") or 2
        used_length = frappe.db.get_value("Batch", item.batch_no, "custom_used_length") or 0
        qty = item.qty or 0

        new_reuse = reuse_count + 1
        new_used_length = used_length + qty

        # Always update used length
        frappe.db.set_value("Batch", item.batch_no, "custom_used_length", new_used_length)

        # User chose to extend reuse → increase max_reuse by 1, no stock deduction
        if item.get("extend_reuse"):
            new_max = max_reuse + 1
            frappe.db.set_value("Batch", item.batch_no, {
                "max_reuse": new_max,
                "reuse_count": new_reuse
            })

            # Prevent stock deduction
            item.qty = 0
            if "transfer_qty" in item.as_dict():
                item.transfer_qty = 0

            frappe.msgprint(
                f"✅ Batch {item.batch_no} reuse extended to {new_max}. "
                f"Now reused {new_reuse} time(s). Stock NOT reduced. "
                f"Total Used Length = {new_used_length}."
            )

        # User chose NO → force stock deduction immediately and reset reuse count
        elif item.get("force_deduct"):
            frappe.db.set_value("Batch", item.batch_no, "reuse_count", 0)

            # Stock deducted normally (qty remains)
            frappe.msgprint(
                f"⚠️ Batch {item.batch_no} reached max reuse ({max_reuse}). "
                f"Stock WILL be deducted. Total Used Length = {new_used_length}."
            )

        # Normal reuse below max_reuse → increment reuse count, no stock deduction
        elif new_reuse < max_reuse:
            frappe.db.set_value("Batch", item.batch_no, "reuse_count", new_reuse)

            # Prevent stock deduction
            item.qty = 0
            if "transfer_qty" in item.as_dict():
                item.transfer_qty = 0

            frappe.msgprint(
                f"ℹ️ Batch {item.batch_no} reused {new_reuse} time(s). "
                f"Stock NOT reduced. Total Used Length = {new_used_length}."
            )

        # Exceeded max reuse without extension → deduct stock and reset reuse count, allow submission
        else:
            frappe.db.set_value("Batch", item.batch_no, "reuse_count", 0)

            # Stock deducted normally (qty remains)
            frappe.msgprint(
                f"⚠️ Batch {item.batch_no} exceeded max reuse ({max_reuse}). "
                f"Stock WILL be deducted. Total Used Length = {new_used_length}."
            )

if doc.stock_entry_type == "Manufacture":
    wo = frappe.get_doc("Work Order", doc.work_order)

    # Run validation only for Coating operation
    if wo.custom_operation_type == "Coating":

        # 1️⃣ Block if any CMPR is Rejected
        rejected_cmpr = frappe.get_all(
            "Coating Machine Production Record",
            filters={
                "work_order": doc.work_order,
                "workflow_state": "Rejected"
            },
            pluck="name"
        )

        if rejected_cmpr:
            frappe.throw(
                f"Cannot proceed with Manufacture Stock Entry. "
                f"CMPR {', '.join(rejected_cmpr)} is in Rejected state. "
                "Please revise and approve the CMPR before continuing."
            )

        # 2️⃣ Check Approved CMPR
        approved_cmpr = frappe.get_all(
            "Coating Machine Production Record",
            filters={
                "work_order": doc.work_order,
                "workflow_state": "Approved",
                "docstatus": 1
            },
            pluck="name"
        )

        if not approved_cmpr:
            frappe.throw(
                f"No Approved CMPR found for Work Order {doc.work_order}. "
                "Please complete and approve CMPR before manufacturing."
            )

# Unlink Work Order before deleting a CMPR
if doc.work_order:
    frappe.db.set_value("Work Order", doc.work_order, "custom_cmpr_ref", None)

# Remove zero-qty rows so ERPNext won't try to cancel SLE for them
new_items = []
removed_rows = []

for item in doc.items:
    if item.qty and item.qty > 0:
        new_items.append(item)
    else:
        removed_rows.append(item.idx)

if removed_rows:
    doc.set("items", new_items)
    frappe.msgprint(f"Removed zero-qty rows {removed_rows} before cancel.")

gsm_actual = float(doc.adhesive_coating_gsm_actual or 0)

if gsm_actual < 30 or gsm_actual > 40:
    frappe.throw(f"Adhesive GSM ({gsm_actual}) is outside the allowed range (30–40). You must send for approval instead of direct approve.")

if doc.damage_found and not doc.notified_stores:

    try:
        # Pause Job Card
        try:
            jc = frappe.get_doc("Job Card", doc.name)
            jc.pause()
            jc.save(ignore_permissions=True)
        except:
            frappe.db.set_value("Job Card", doc.name, "status", "On Hold")

        # Notification message
        message = f"""
🚨 Material Damage Reported

Job Card: {doc.name}
Workstation: {doc.workstation or 'Not Specified'}
Reported By: {frappe.session.user}
Remarks: {doc.damage_remarks or 'No remarks provided.'}

Please arrange replacement or material issue immediately.
"""

        # Get valid users with Stores User role
        store_users = frappe.get_all(
            "Has Role",
            filters={"role": "Stock Manager"},
            fields=["parent as user"]
        )
        valid_store_users = [u.user for u in store_users if frappe.db.exists("User", u.user)]

        # Send system notifications
        for user in valid_store_users:
            frappe.get_doc({
                "doctype": "Notification Log",
                "subject": f"Material Damage in Job Card {doc.name}",
                "email_content": message,
                "for_user": user,
                "type": "Alert",
                "document_type": "Job Card",
                "document_name": doc.name,
            }).insert(ignore_permissions=True)

        # Mark as notified
        frappe.db.set_value("Job Card", doc.name, "notified_stores", 1)

        frappe.msgprint("⚠️ Job Card paused and Stores notified successfully.")

    except Exception as e:
        frappe.msgprint(f"Error pausing Job Card or sending notification: {e}")

# Automatically set FG Warehouse based on the BOM's default warehouse
if doc.bom_no:
    bom = frappe.get_doc("BOM", doc.bom_no)
    default_fg_wh = bom.get("custom_default_fg_warehouse")
    if default_fg_wh:
        doc.fg_warehouse = default_fg_wh

for item in doc.items:
    if not item.item_code:
        continue

    # Fetch item UOMs as dict to avoid unpack errors
    item_data = frappe.db.get_value(
        "Item",
        item.item_code,
        ["purchase_uom", "stock_uom"],
        as_dict=True
    )

    if not item_data:
        continue

    purchase_uom = item_data.purchase_uom
    stock_uom = item_data.stock_uom

    if not purchase_uom or not stock_uom:
        continue

    # If user already selected Purchase UOM (example: KG), skip conversion
    if item.uom == purchase_uom:
        continue

    # Convert only when UOM = Stock UOM (example: Gram → KG)
    if item.uom == stock_uom and purchase_uom != stock_uom:

        # Get conversion factor for purchase UOM
        cf = frappe.db.get_value(
            "UOM Conversion Detail",
            {"parent": item.item_code, "uom": purchase_uom},
            "conversion_factor"
        )

        if not cf:
            continue

        try:
            # Convert stock UOM quantity → purchase UOM quantity
            item.qty = float(item.qty) / float(cf)
            item.uom = purchase_uom

        except Exception as e:
            frappe.log_error(f"UOM Conversion Error for {item.item_code}: {e}")
            continue

# Job Card (before_submit)
# Record produced qty to a helper field on the linked Work Order
# so later valuation/consumption logic can use the actual produced quantity.

def flt(v):
    try:
        return float(v or 0)
    except:
        return 0.0

# Detect produced qty using safest field name
produced_qty = flt(
    doc.get('produced_qty')
    or doc.get('completed_qty')
    or doc.get('total_completed_qty')
    or 0
)

# If nothing produced, do nothing
if produced_qty <= 0:
    pass
else:
    # Update Work Order helper field
    if doc.get('work_order'):
        try:
            wo = frappe.get_doc('Work Order', doc.work_order)
            prev = flt(wo.get('_produced_qty_from_jobcards') or 0)
            wo.set('_produced_qty_from_jobcards', prev + produced_qty)
            wo.save(ignore_permissions=True)
        except:
            frappe.log_error(frappe.get_traceback(), 'Job Card: WO qty update failed')

# Stock Entry (after_submit)
# When a damaged return Stock Entry (_is_damaged_return = 1) is submitted,
# update Job Card and Work Order custom fields.

def flt(v):
    try:
        return float(v or 0)
    except:
        return 0.0

# Process only damaged-return entries
if doc.get('_is_damaged_return'):
    
    # Get linked Job Card and Work Order
    jc = doc.get('job_card') or doc.get('_on_behalf_of_job_card')
    wo = doc.get('work_order')

    # Calculate total returned qty
    total_returned = 0
    for d in doc.items:
        total_returned += flt(d.transfer_qty)

    # --- Update Job Card ---
    if jc:
        try:
            job = frappe.get_doc('Job Card', jc)
            previous = flt(job.get('_returned_qty') or 0)
            job.set('_returned_qty', previous + total_returned)
            job.save(ignore_permissions=True)
        except:
            frappe.log_error(frappe.get_traceback(), 'Damaged Return: Job Card update failed')

    # --- Update Work Order ---
    if wo:
        try:
            w = frappe.get_doc('Work Order', wo)
            previous = flt(w.get('_returned_raw_material') or 0)
            w.set('_returned_raw_material', previous + total_returned)
            w.save(ignore_permissions=True)
        except:
            frappe.log_error(frappe.get_traceback(), 'Damaged Return: Work Order update failed')

for row in doc.items:
    if row.batch_no:
        batch = frappe.get_doc("Batch", row.batch_no)

        if batch.expiry_date:
            expiry = frappe.utils.getdate(batch.expiry_date)
            if expiry <= frappe.utils.getdate(frappe.utils.today()):
                frappe.throw(
                    f"Batch {row.batch_no} is expired (Expiry: {batch.expiry_date}) and cannot be used."
                )

if doc.production_item and doc.fg_warehouse and doc.docstatus == 0:

    bin_data = frappe.db.get_value(
        "Bin",
        {
            "item_code": doc.production_item,
            "warehouse": doc.fg_warehouse
        },
        ["actual_qty", "reserved_qty"],
        as_dict=True
    )

    actual_qty = 0
    reserved_qty = 0

    if bin_data:
        actual_qty = bin_data.get("actual_qty") or 0
        reserved_qty = bin_data.get("reserved_qty") or 0

    available_qty = actual_qty - reserved_qty
    required_qty = doc.qty or 0
    balance_qty = required_qty - available_qty

    # If full stock available
    if balance_qty <= 0:
        frappe.throw(
            "Sufficient stock available in " + str(doc.fg_warehouse)
        )

    # If partial stock available
    if available_qty > 0:
        if required_qty != balance_qty:
            doc.qty = balance_qty
            doc.required_items = []

stock_map = {}

for item in doc.get("po_items"):

    item.available_stock = 0
    item.qty_to_produce = item.planned_qty or 0

    if not item.item_code or not item.warehouse:
        continue

    key = item.item_code + "||" + item.warehouse

    if key not in stock_map:
        actual_qty = frappe.db.get_value(
            "Bin",
            {
                "item_code": item.item_code,
                "warehouse": item.warehouse
            },
            "actual_qty"
        ) or 0

        stock_map[key] = actual_qty

    remaining_stock = stock_map[key]
    planned = item.planned_qty or 0

    if remaining_stock >= planned:
        item.available_stock = planned
        item.qty_to_produce = 0
        stock_map[key] = remaining_stock - planned
    else:
        item.available_stock = remaining_stock
        item.qty_to_produce = planned - remaining_stock
        stock_map[key] = 0

for item in doc.po_items:

    if item.item_code and item.warehouse:

        actual_qty = frappe.db.get_value(
            "Bin",
            {
                "item_code": item.item_code,
                "warehouse": item.warehouse
            },
            "actual_qty"
        ) or 0

        item.available_stock = actual_qty

# ======================================
# JOB CARD -> CMPR AUTO CREATION
# Trigger : Before Save
# ======================================

if doc.work_order:

    def to_float(val):
        try:
            return float(val or 0)
        except:
            return 0.0

    wo_operation = frappe.db.get_value(
        "Work Order",
        doc.work_order,
        "custom_operation_type"
    ) or ""

    if wo_operation == "Coating":

        current_completed_qty = to_float(doc.total_completed_qty)

        # Do nothing if no production completed
        if current_completed_qty > 0:

            # ======================================
            # Find already recorded CMPR qty
            # ======================================

            cmpr_qty = frappe.db.sql("""
                SELECT IFNULL(SUM(production_qty),0)
                FROM `tabNew CMPR`
                WHERE job_card=%s
            """, (doc.name,))

            already_recorded_qty = 0.0

            if cmpr_qty and cmpr_qty[0]:
                already_recorded_qty = to_float(cmpr_qty[0][0])

            new_completed_qty = (
                current_completed_qty
                - already_recorded_qty
            )

            # Create CMPR only for new production
            if new_completed_qty > 0:

                cloth_lot = ""
                total_fabric_qty = 0.0

                quilon_batch = ""
                adhesive_batch = ""

                stock_entries = frappe.get_all(
                    "Stock Entry",
                    filters={
                        "work_order": doc.work_order,
                        "docstatus": 1,
                        "purpose": "Material Transfer for Manufacture"
                    },
                    fields=["name", "creation"],
                    order_by="creation asc"
                )

                for se in stock_entries:

                    se_items = frappe.get_all(
                        "Stock Entry Detail",
                        filters={
                            "parent": se.name
                        },
                        fields=[
                            "item_code",
                            "batch_no",
                            "qty",
                            "serial_and_batch_bundle"
                        ]
                    )

                    for row in se_items:

                        item_code = row.get("item_code") or ""
                        batch_no = row.get("batch_no") or ""
                        qty_val = to_float(row.get("qty"))
                        bundle = row.get("serial_and_batch_bundle")

                        material_type = frappe.db.get_value(
                            "Item",
                            item_code,
                            "custom_material_type"
                        )

                        # FABRIC
                        if material_type == "Fabric":

                            if bundle:

                                bundle_rows = frappe.get_all(
                                    "Serial and Batch Entry",
                                    filters={
                                        "parent": bundle
                                    },
                                    fields=[
                                        "batch_no",
                                        "qty"
                                    ]
                                )

                                for b in bundle_rows:

                                    lot_no = b.get("batch_no") or ""

                                    total_fabric_qty += abs(
                                        to_float(b.get("qty"))
                                    )

                                    if lot_no:

                                        if not cloth_lot:
                                            cloth_lot = lot_no

                                        elif lot_no not in cloth_lot:
                                            cloth_lot += ", " + lot_no

                            else:

                                total_fabric_qty += qty_val

                                if batch_no:

                                    if not cloth_lot:
                                        cloth_lot = batch_no

                                    elif batch_no not in cloth_lot:
                                        cloth_lot += ", " + batch_no

                        # QUILON
                        elif material_type == "Quilon":

                            if batch_no and not quilon_batch:
                                quilon_batch = batch_no

                        # ADHESIVE
                        elif material_type == "Adhesive":

                            if batch_no and not adhesive_batch:
                                adhesive_batch = batch_no

                if not cloth_lot:
                    cloth_lot = "N/A"

                cmpr = frappe.new_doc("New CMPR")

                cmpr.work_order = doc.work_order
                cmpr.job_card = doc.name

                # ======================================
                # Production Quantities
                # ======================================

                cmpr.production_qty = new_completed_qty
                cmpr.completed_qty = current_completed_qty

                cmpr.colour = frappe.db.get_value(
                    "Work Order",
                    doc.work_order,
                    "so_colour"
                ) or ""

                cmpr.cloth_article = frappe.db.get_value(
                    "Work Order",
                    doc.work_order,
                    "production_item"
                ) or ""

                cmpr.stores_issued_meters = total_fabric_qty
                cmpr.cloth_lot = cloth_lot

                cmpr.quilon_recd_from_stores_kgsbatch_no = quilon_batch
                cmpr.glue_recd_from_stores_kgsbatch_no = adhesive_batch

                bom_no = frappe.db.get_value(
                    "Work Order",
                    doc.work_order,
                    "bom_no"
                )

                cmpr.quilon_coating_gsm_spec = 0.0
                cmpr.adhesive_coating_gsm_spec = 0.0

                if bom_no:

                    bom_items = frappe.get_all(
                        "BOM Item",
                        filters={
                            "parent": bom_no
                        },
                        fields=[
                            "item_code",
                            "qty"
                        ]
                    )

                    for b in bom_items:

                        item_code = b.get("item_code") or ""
                        qty_val = to_float(b.get("qty"))

                        material_type = frappe.db.get_value(
                            "Item",
                            item_code,
                            "custom_material_type"
                        )

                        if material_type == "Quilon":
                            cmpr.quilon_coating_gsm_spec = qty_val

                        elif material_type == "Adhesive":
                            cmpr.adhesive_coating_gsm_spec = qty_val

                try:

                    cmpr.insert(
                        ignore_permissions=True,
                        ignore_mandatory=True
                    )

                    frappe.msgprint(
                        "CMPR Created : "
                        + str(cmpr.name)
                        + " | Production Qty : "
                        + str(new_completed_qty)
                    )

                except Exception as e:

                    frappe.log_error(
                        str(e),
                        "CMPR Creation Error"
                    )

    else:

        frappe.msgprint(
            "Skipping CMPR creation: Operation Type is "
            + str(wo_operation)
        )

