employees = frappe.get_all(
    "Employee",
    filters={"status": "Active"},
    fields=["name", "employee_name", "holiday_list", "company"]
)

today = frappe.utils.today()

for emp in employees:

    if not emp.holiday_list:
        continue

    holiday = frappe.db.get_value(
        "Holiday",
        {
            "parent": emp.holiday_list,
            "holiday_date": today
        },
        ["weekly_off", "description"],
        as_dict=True
    )

    if not holiday:
        continue

    attendance_exists = frappe.db.exists(
        "Attendance",
        {
            "employee": emp.name,
            "attendance_date": today
        }
    )

    if attendance_exists:
        continue

    holiday_type = (
        "Week Off"
        if holiday.weekly_off
        else "Holiday"
    )

    attendance = frappe.get_doc({
        "doctype": "Attendance",
        "employee": emp.name,
        "employee_name": emp.employee_name,
        "attendance_date": today,
        "company": emp.company,
        "status": "Present",
        "custom_holiday_type": holiday_type,
        "custom_mispunch": 0
    })

    attendance.insert(ignore_permissions=True)

    try:
        attendance.submit()
    except Exception:
        pass
